    public void visitConstructor(@NonNull JavaContext context, @NonNull UCallExpression node, @NonNull PsiMethod constructor) {
        List<UExpression> args = node.getValueArguments();
        if (args.size() != 2) return;
        UExpression arg = args.get(1);
        // If ComponentName constructed inline
        if (arg instanceof UCallExpression) {
            UCallExpression call = (UCallExpression) arg;
            PsiMethod method = call.resolve();
            if (method != null && method.isConstructor() && COMPONENT_NAME.equals(method.getContainingClass().getQualifiedName())) {
                List<UExpression> cnArgs = call.getValueArguments();
                if (cnArgs.size() == 2) {
                    UExpression classArg = cnArgs.get(1);
                    if (classArg instanceof UClassLiteralExpression) {
                        PsiClass cls = ((UClassLiteralExpression) classArg).getDeclaration();
                        if (cls != null) {
                            checkJobService(context, node, cls);
                            return;
                        }
                    }
                }
            }
        }
        // If class literal directly? Not for Builder.
    }

    private void checkJobService(JavaContext context, UCallExpression node, PsiClass cls) {
        if (!context.getEvaluator().extendsClass(cls, JOB_SERVICE, false)) {
            context.report(ISSUE, node, context.getLocation(node),
                String.format("The service class %1$s must extend android.app.job.JobService", cls.getQualifiedName()));
            return;
        }
        // check manifest
        String fqcn = cls.getQualifiedName();
        if (fqcn == null) return;
        Project project = context.getMainProject();
        String pkg = project.getPackage();
        if (pkg == null) return;
        Document manifest = project.getManifestDom();
        if (manifest == null) return;
        Element application = ... find application
        NodeList services = application.getElementsByTagName("service");
        boolean found = false;
        for (...) {
            Element service = ...;
            String name = service.getAttributeNS(ANDROID_URI, "name");
            String serviceClass = getFqcn(pkg, name);
            if (fqcn.equals(serviceClass)) {
                found = true;
                String permission = service.getAttributeNS(ANDROID_URI, "permission");
                if (!BIND_JOB_SERVICE.equals(permission)) {
                    context.report(ISSUE, node, context.getLocation(node),
                        String.format("The service %1$s must require android.permission.BIND_JOB_SERVICE", fqcn));
                }
                break;
            }
        }
        if (!found) {
            context.report(ISSUE, node, context.getLocation(node),
                String.format("The service %1$s must be registered in the manifest", fqcn));
        }
    }
}
