private void checkClass(@NonNull JavaContext context, @NonNull UCallExpression node,
        @NonNull PsiClass cls) {
    if (!context.getEvaluator().extendsClass(cls, JOB_SERVICE, false)) {
        String fqcn = cls.getQualifiedName();
        context.report(ISSUE, node, context.getLocation(node),
                "The service " + (fqcn != null ? fqcn : cls.getName())
                        + " must extend android.app.job.JobService");
        return;
    }
    String fqcn = cls.getQualifiedName();
    if (fqcn == null) return;
    checkManifest(context, node, fqcn);
}

private void checkClassName(@NonNull JavaContext context, @NonNull UCallExpression node,
        @NonNull String className) {
    Project project = context.getMainProject();
    String packageName = project.getPackage();
    if (packageName == null) {
        Document manifest = project.getManifestDom();
        if (manifest != null) {
            packageName = manifest.getDocumentElement().getAttribute("package");
        }
    }
    String fqcn = normalizeServiceName(packageName, className);
    PsiClass cls = context.getEvaluator().findClass(fqcn);
    if (cls == null) {
        // Can't resolve; don't flag extends
        checkManifest(context, node, fqcn);
    } else {
        checkClass(context, node, cls);
    }
}
